pm.test("Matches documented StudentResponse schema", () => {
  const specText = pm.collectionVariables.get("contract");
  pm.expect(specText, "Run Fetch Contract first").to.be.a("string").and.not.empty;
  const spec = JSON.parse(specText);
  const Ajv = require('ajv');
  const ajv = new Ajv({allErrors:true,unknownFormats:'ignore',schemaId:'auto',validateSchema:false,logger:false});
  ajv.addSchema(spec,'spec');
  const entries = Array.isArray(responsePayload) ? responsePayload : [responsePayload];
  entries.forEach((entry,i) => {
    const valid = ajv.validate({$ref:'spec#/components/schemas/StudentResponse'},entry);
    pm.expect(valid, 'Item '+i+': '+ajv.errorsText()).to.be.true;
    const allowed = spec.components.schemas.StudentResponse.properties || {};
    pm.expect(Object.keys(entry).filter(k=>!(k in allowed)), 'Undocumented fields in item '+i).to.be.empty;
  });
});

